/* ══════════════════════════════════════════════════════════════════
   KoreaPlus — Static SEO page generator
   Reads data.js + detail-data.js and emits crawlable HTML pages:
     • /guide/places/{slug}.html       — 90 place/topic pages
     • /guide/guide/{slug}.html        — city guides + "best of" + months
     • /guide/itinerary/{slug}.html    — day-by-day itinerary templates
     • /guide/explore.html             — internal-linking hub
     • /guide/sitemap.xml              — full sitemap (regenerated)
   Each page ships JSON-LD (TouristAttraction / Article / ItemList /
   FAQPage / BreadcrumbList) + canonical + OpenGraph.
   Run:  node build-seo.cjs
   ══════════════════════════════════════════════════════════════════ */
'use strict';
const fs = require('fs');
const path = require('path');
const vm = require('vm');
// Layer-0 shared helpers for the seo-<name>.cjs generated-content modules.
// Pure (no build-seo coupling); injected into every module via the CTX object
// assembled just before the build loop. See `const CTX = {...}` below.
const __ld = require('./modules/seo-ld.cjs');
const __derive = require('./modules/seo-derive.cjs');
const __kpm = require('./modules/seo-kpop-media.cjs');

const ORIGIN = 'https://koreaplus-lifes.com';
const BASEP = '/guide/';
const OUT = __dirname;
const TODAY = new Date().toISOString().slice(0, 10);
// Release dates are Korean dates; comparing them against a UTC "today" marks a
// release as upcoming for nine hours after it is already out.
const TODAY_KST = new Date(Date.now() + 9 * 3600_000).toISOString().slice(0, 10);

// ── Load data ───────────────────────────────────────────────────────
function loadData() {
  const ctx = {}; vm.createContext(ctx);
  vm.runInContext(fs.readFileSync(path.join(OUT, 'data.js'), 'utf8') +
    '\nthis.KOREA_DATA=KOREA_DATA; this.CITIES=CITIES;', ctx);
  const dctx = { window: {} }; vm.createContext(dctx);
  vm.runInContext(fs.readFileSync(path.join(OUT, 'detail-data.js'), 'utf8'), dctx);
  return { KOREA_DATA: ctx.KOREA_DATA, CITIES: ctx.CITIES, DETAIL: dctx.window.DETAIL_DATA || {} };
}
const { KOREA_DATA, CITIES, DETAIL } = loadData();

// Localized city-guide content (generated by the city-guides-l10n workflow).
// Shape: { "Seoul": { ja: {guide}, zh: {guide}, es: {guide} }, ... }. Optional —
// build still works without it.
let CITY_L10N = {};
try { CITY_L10N = JSON.parse(fs.readFileSync(path.join(OUT, 'city-l10n.json'), 'utf8')); } catch { /* none yet */ }
// Localized blog translations. Shape: { "<slug>": { ja:{h1,title,metaDesc,body,faq[]}, zh:{}, es:{} } }
let BLOG_L10N = {};
try { BLOG_L10N = JSON.parse(fs.readFileSync(path.join(OUT, 'blog-l10n.json'), 'utf8')); } catch { /* none yet */ }
// Localized itineraries. Shape: { "<slug>": { ja:{h1,title,metaDesc,lead,days:[{label,plan}],tips[],faq[]}, zh, es } }
let ITIN_L10N = {};
try { ITIN_L10N = JSON.parse(fs.readFileSync(path.join(OUT, 'itinerary-l10n.json'), 'utf8')); } catch { /* none yet */ }
// K-Pop history pages (9 languages). Shape: { "<slug>": { en:{h1,title,metaDesc,lead,sections:[{h,body}],faq:[{q,a}]}, ko, ja, zh, es, fr, de, pt, id } }
let KPOP_HIST = {};
try { KPOP_HIST = JSON.parse(fs.readFileSync(path.join(OUT, 'kpop-history.json'), 'utf8')); } catch { /* none yet */ }
let KPOP_ROSTER = [];
try { KPOP_ROSTER = require('./kpop-data.js').KPOP_ROSTER || []; } catch { /* roster optional */ }
// K-Pop member enrichment (lightstick + verified member birthdays). Browser
// global file (window.KPOP_ENRICH); loaded via vm. Shape keyed by group id:
//   { "<id>": { lightstick?, color?, bdays: [[memberName, "YYYY-MM-DD"], ...] } }
// CTX.ENRICH for the generated-content modules. Optional — build works without.
let KPOP_ENRICH = {};
try { const ec = { window: {} }; vm.createContext(ec); vm.runInContext(fs.readFileSync(path.join(OUT, 'kpop-enrich.js'), 'utf8'), ec); KPOP_ENRICH = ec.window.KPOP_ENRICH || {}; } catch { /* none yet */ }
// K-Pop build-time snapshots — the same two files the hub loads at runtime, so
// generated pages and the SPA never disagree about a release date or a photo.
//   kpop-discog.js → { "<id>": { artistId, artistName, asOf, albums:[{title,date,year,art}] } }
//   kpop-images.js → { "<id>": { src, artist, license, page } }  ← licence-verified
// Regenerate with tools/gen-kpop-{discog,images}.cjs. Optional: absent → the
// discography sections and photos simply don't render.
let KPOP_DISCOG = {};
try { const dc = { window: {} }; vm.createContext(dc); vm.runInContext(fs.readFileSync(path.join(OUT, 'kpop-discog.js'), 'utf8'), dc); KPOP_DISCOG = dc.window.KPOP_DISCOG || {}; } catch { /* none yet */ }
let KPOP_IMAGES = {};
try { const ic = { window: {} }; vm.createContext(ic); vm.runInContext(fs.readFileSync(path.join(OUT, 'kpop-images.js'), 'utf8'), ic); KPOP_IMAGES = ic.window.KPOP_IMAGES || {}; } catch { /* none yet */ }
// Per-city Unsplash photos (element 5 image SEO). { City: { raw, alt, by, byUrl, link } }
// From prefetch-images.cjs (key never stored here). Hotlinked from the Unsplash
// CDN with photographer attribution per Unsplash API guidelines.
let CITY_IMAGES = {};
try { CITY_IMAGES = JSON.parse(fs.readFileSync(path.join(OUT, 'city-images.json'), 'utf8')); } catch { /* none yet */ }
// Translated category-hub UI strings (en + 8 locales); built by the hub-l10n workflow.
let HUB_L10N = {};
try { HUB_L10N = JSON.parse(fs.readFileSync(path.join(OUT, 'hub-l10n.json'), 'utf8')); } catch { /* none yet → localized hubs skipped */ }

// ── Helpers ─────────────────────────────────────────────────────────
const slug = s => String(s).toLowerCase()
  .replace(/['']/g, '').replace(/&/g, ' and ')
  .replace(/[^a-z0-9]+/g, '-').replace(/^-+|-+$/g, '');
const esc = s => String(s == null ? '' : s)
  .replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;').replace(/"/g, '&quot;');
const enc = s => encodeURIComponent(s);
// JSON.stringify's output lands raw inside a <script> element, so any literal
// "</script" in the data would close it early and spill the rest of the schema
// into the document. Album titles come from the Apple snapshot and already carry
// angle brackets ("<HELLO MONSTERS>"), so this is one release title away from
// breaking every profile and year page for that act. \u-escaping the three
// characters is still valid JSON and parses to the identical object.
const _LDESC = { '<': '\\u003c', '>': '\\u003e', '&': '\\u0026' };
const jsonld = obj => `<script type="application/ld+json">${JSON.stringify(obj).replace(/[<>&]/g, c => _LDESC[c])}</script>`;
const cityImg = c => CITY_IMAGES[c] || null;
// Wikimedia Commons thumbnails are already sized (~1280px) and ignore Unsplash-style
// query params — pass them through unchanged; only Unsplash URLs get the resize query.
const imgUrl = (raw, w, h) => /upload\.wikimedia\.org/.test(raw)
  ? raw
  : raw + (raw.includes('?') ? '&' : '?') + `w=${w}` + (h ? `&h=${h}&fit=crop` : '') + `&q=80&fm=jpg&auto=format`;
const ogImgFor = im => im ? imgUrl(im.raw, 1200, 630) : null;
// Photo credit honoring each source's license (Wikimedia requires author + license).
function photoCredit(im) {
  if (im.source === 'wikimedia') {
    return `📷 <a href="${esc(im.byUrl)}" target="_blank" rel="noopener nofollow">${esc(im.by)}</a> / <a href="${esc(im.link || im.byUrl)}" target="_blank" rel="noopener nofollow">Wikimedia Commons</a>${im.license ? ' (' + esc(im.license) + ')' : ''}`;
  }
  return `📷 <a href="${esc(im.byUrl)}" target="_blank" rel="noopener nofollow">${esc(im.by)}</a> / <a href="https://unsplash.com/?utm_source=koreaplus&utm_medium=referral" target="_blank" rel="noopener nofollow">Unsplash</a>`;
}
function heroFigure(im, label) {
  if (!im) return '';
  const alt = label ? (label + (im.alt ? ' — ' + im.alt : '')) : (im.alt || '');
  return `<figure class="seo-hero-img" style="margin:0 0 18px;border-radius:14px;overflow:hidden;border:1px solid var(--border,rgba(255,255,255,.08))">` +
    `<img src="${esc(imgUrl(im.raw, 1000, 480))}" alt="${esc(alt)}" width="1000" height="480" loading="eager" fetchpriority="high" style="width:100%;height:auto;display:block;aspect-ratio:25/12;object-fit:cover">` +
    `<figcaption style="font-size:11px;color:var(--text3,#8a93a0);padding:6px 10px">${photoCredit(im)}</figcaption></figure>`;
}
// Write to a sibling temp file and rename over the target instead of truncating
// it in place. Two reasons, both real here:
//   * On Windows, truncating a file that some other process has memory-mapped
//     fails with ERROR_USER_MAPPED_FILE, which libuv surfaces as an opaque
//     `UNKNOWN (-4094)` and which aborted this build mid-run. Rename replaces
//     the directory entry and is unaffected.
//   * A rename is atomic, so a reader (the other session, a dev server, a
//     half-finished run) never sees a partially written page.
// Every generated page — shell()-built or hand-rolled by a module — goes through
// here, so this is where two document-wide invariants are enforced:
//   1. dir="rtl" on <html> for the RTL languages. shell() emits it itself, but
//      the K-pop tool EMBED builds its own <!DOCTYPE> document and bypassed the
//      shell entirely, which is why ar/embed/kpop-idol-birthday-finder.html was
//      the one Arabic page in the repo laid out left-to-right. Enforcing it at
//      the write boundary covers every future generator that hand-rolls a
//      document too, instead of waiting for the next one to forget.
//   2. PAGE_H1 — the plain-text <h1> of everything we wrote, keyed by the same
//      OUT-relative path. buildKpopBrowse() uses it to label directory links in
//      the page's own language without duplicating any generator's copy.
const PAGE_H1 = new Map();
const writePage = (rel, html) => {
  const fp = path.join(OUT, rel);
  const key = String(rel).replace(/\\/g, '/').replace(/^\/+/, '');
  const htmlTag = /<html\s[^>]*>/i.exec(html);
  if (htmlTag && !/\sdir\s*=/i.test(htmlTag[0])) {
    const lm = /\slang="([^"]+)"/i.exec(htmlTag[0]);
    if (lm && RTL_LANGS.has(lm[1])) {
      html = html.replace(htmlTag[0], htmlTag[0].replace(/>$/, ' dir="rtl">'));
    }
  }
  const h1 = /<h1[^>]*>([\s\S]*?)<\/h1>/i.exec(html);
  if (h1) PAGE_H1.set(key, h1[1].replace(/<[^>]+>/g, '').replace(/\s+/g, ' ').trim());
  fs.mkdirSync(path.dirname(fp), { recursive: true });
  const tmp = fp + '.tmp' + process.pid;
  // The write is inside the try too: a crash there (ENOSPC, EPERM) otherwise
  // leaves the partial *.tmp<pid> behind, and deploy tars the whole tree.
  try {
    fs.writeFileSync(tmp, html);
    fs.renameSync(tmp, fp);
  } catch (e) {
    try { fs.unlinkSync(tmp); } catch { /* best effort */ }
    throw e;
  }
};

const CAT_META = {
  food:      { label: 'Korean Food',     icon: '🍜', noun: 'dish' },
  travel:    { label: 'Travel',          icon: '✈️', noun: 'destination' },
  transport: { label: 'Transport',       icon: '🚄', noun: 'option' },
  companies: { label: 'Companies',       icon: '🏢', noun: 'company' },
  kbeauty:   { label: 'K-Beauty',        icon: '💄', noun: 'topic' },
  kpop:      { label: 'K-Pop & Culture', icon: '🎤', noun: 'experience' },
  shopping:  { label: 'Shopping',        icon: '🛍️', noun: 'spot' },
  history:   { label: 'History',         icon: '📜', noun: 'topic' },
};
const ATTRACTION_CATS = new Set(['travel', 'shopping', 'kbeauty', 'kpop']);
// clean, keyword-rich category page slugs (used by category pages + place breadcrumbs)
const CAT_SLUG = {
  food: 'best-korean-food', travel: 'best-places-to-visit-in-korea',
  transport: 'korea-transport-guide', companies: 'top-korean-companies',
  kbeauty: 'k-beauty-guide', kpop: 'k-pop-and-culture-guide',
  shopping: 'best-shopping-in-korea', history: 'korean-history-guide',
};

// ── Affiliate config — Agoda only ───────────────────────────────────
// Single affiliate partner: Agoda (hotels). The CID below is the public
// affiliate site id; it earns commission on every deep link. Live hotel
// cards (with real prices) are layered on at runtime by the Worker's
// /api/aff endpoint, which calls the Agoda Long Tail Search API with the
// secret API key. If the Worker/API is unavailable, the static cid deep
// link below still monetizes — so every page works with or without JS.
const AGODA_CID = '1952761';
// Agoda canonical city landing pages (slug verified) → city-targeted deep
// links. Unknown cities fall back to the South-Korea country page.
const AGODA_CITY = {
  Seoul: 'seoul-kr', Busan: 'busan-kr', Jeju: 'jeju-kr', Incheon: 'incheon-kr',
  Gyeongju: 'gyeongju-kr', Jeonju: 'jeonju-kr', Andong: 'andong-kr', Yeosu: 'yeosu-kr',
};
const AGODA_HL = { en: '', ja: 'ja-jp', zh: 'zh-cn', es: 'es-es' };
function agodaUrl(city, lang = 'en') {
  const c = AGODA_CITY[city];
  const pathPart = c ? `city/${c}.html` : 'country/south-korea.html';
  const hl = AGODA_HL[lang] ? `&hl=${AGODA_HL[lang]}` : '';
  return `https://www.agoda.com/${pathPart}?cid=${AGODA_CID}${hl}`;
}
