  fr: { attractionsH: '🏯 À voir', eatH: '🍜 Où manger', gettingH: '🚄 Y aller et se déplacer', tipsH: '💡 Conseils', faqH: '❓ FAQ', enBtn: '🇬🇧 English', planBtn: '🗺️ Créer mon itinéraire', moreH: '🔗 Guides liés' },
