function buildCompare(c) {
  const url = `${BASEP}guide/${c.slug}.html`;
  const title = `${c.h1} (2026) | KoreaPlus`;
  const trail = [{ name: 'Home', url: BASEP }, { name: 'Comparisons', url: `${BASEP}explore.html` }, { name: c.h1, url }];
  let body = bcHtml(trail);
  body += `<p class="lead">${c.intro}</p>`;
  body += `<h2>📊 Side by side</h2>` + tbl(c.rows);
  body += `<h2>❓ FAQ</h2><div class="seo-faq">${c.qa.map(([q, a]) => `<details><summary>${esc(q)}</summary><p>${esc(a)}</p></details>`).join('')}</div>`;
  body += `<h2>🔗 Keep planning</h2><div class="seo-linklist">${c.rel.map(([l, h]) => `<a href="${h}">${esc(l)}</a>`).join('')}</div>`;
  body += affHtml('🎫 Book either trip', { city: 'Seoul', cat: 'travel', q: '' });
  body += ctaHtml('Still deciding?', 'Tell the AI planner your dates and interests — it routes the best option for you.');
  const hero = `<header class="seo-hero"><span class="emoji">${c.emoji}</span><h1>${esc(c.h1)}</h1><div class="meta"><span class="seo-badge">Comparison</span><span class="seo-badge">2026</span></div></header>`;
  const article = { '@context': 'https://schema.org', '@type': 'Article', headline: c.h1, description: c.desc, datePublished: TODAY, dateModified: TODAY, author: { '@type': 'Organization', name: 'KoreaPlus' }, publisher: { '@type': 'Organization', name: 'KoreaPlus-Lifes', logo: { '@type': 'ImageObject', url: ORIGIN + '/guide/icons/kplus.svg' } }, image: ORIGIN + '/guide/og-image.jpg', mainEntityOfPage: ORIGIN + url };
  // G02 — enumerate the compared options as an ItemList (the header row of
  // c.rows lists the options; cell [0][0] is the row-label column → skip it).
  // No fabrication: option names are mirrored verbatim from the table header.
  const optionNames = Array.isArray(c.rows) && c.rows.length
    ? c.rows[0].slice(1).map(s => String(s || '').trim()).filter(Boolean) : [];
  const compareList = optionNames.length
    ? __ld.itemListLD(optionNames.map(name => ({ name })), { name: c.h1, description: c.desc, origin: ORIGIN })
    : null;
  writePage(`guide/${c.slug}.html`, shell({ url, title, desc: c.desc, keywords: '', schemas: [article, compareList, breadcrumbLD(trail), faqLD(c.qa)].filter(Boolean), hero, body }));
  return url;
}

// ══════════════════════════════════════════════════════════════════
// 14) CITY FOOD PAGES + 15) SEASONAL HUBS
// ══════════════════════════════════════════════════════════════════
function buildCityFood(city) {
  const n = city.name;
  const local = ALL.filter(i => i.cat === 'food' && ((i.region || '').includes(n) || (i.mapQ || '').includes(n)));
  const national = ALL.filter(i => i.cat === 'food' && !local.includes(i));
  const pool = [...local, ...national].slice(0, 8);
  const url = `${BASEP}guide/best-food-in-${slug(n)}.html`;
  const h1 = `Best Food in ${n}: What to Eat & Where`;
  const title = `${h1} (2026) | KoreaPlus`;
  const desc = `What to eat in ${n} (${city.kr}): ${pool.slice(0, 4).map(i => i.name).join(', ')} and more — with prices, insider tips and where locals actually eat.`;
  const trail = [{ name: 'Home', url: BASEP }, { name: n, url: `${BASEP}guide/things-to-do-in-${slug(n)}.html` }, { name: 'Best Food', url }];
  let body = bcHtml(trail);
  body += `<p class="lead">${esc(n)} is one of Korea's great eating cities. Here's what to order — tap any dish for the full guide with prices and the best spots.</p>`;
  body += `<div class="seo-grid">${pool.map(cardHtml).join('')}</div>`;
  body += `<h2>💡 Eating tips for ${esc(n)}</h2><ul class="tips"><li>Side dishes (banchan) are free and refillable — ask with "더 주세요".</li><li>Lunch set menus give the best value; save dinner for BBQ and stews.</li><li>Markets peak in the evening from 5pm; bring some cash.</li></ul>`;
  const qa = [[`What food is ${n} famous for?`, `${n} is best known for ${pool.slice(0, 3).map(i => i.name).join(', ')} — see the full list above with prices and where to try each.`]];
  body += `<h2>❓ FAQ</h2><div class="seo-faq">${qa.map(([q, a]) => `<details><summary>${esc(q)}</summary><p>${esc(a)}</p></details>`).join('')}</div>`;
  body += affHtml(`🍜 Food tours in ${n}`, { city: n, cat: 'food', q: '' });
  body += ctaHtml(`Eating your way through ${n}?`, 'The AI planner weaves these dishes into a day-by-day route.');
  const hero = `<header class="seo-hero"><span class="emoji">🍜</span><h1>${esc(h1)}</h1><div class="kr" lang="ko">${esc(city.kr)}</div><div class="meta"><span class="seo-badge region">${pool.length} picks</span></div></header>`;
  const itemList = { '@context': 'https://schema.org', '@type': 'ItemList', name: h1, itemListElement: pool.map((it, i) => ({ '@type': 'ListItem', position: i + 1, name: it.name, url: ORIGIN + `${BASEP}places/${it.slug}.html` })) };
  writePage(`guide/best-food-in-${slug(n)}.html`, shell({ url, title, desc, keywords: '', schemas: [itemList, breadcrumbLD(trail), faqLD(qa)], hero, body }));
  return url;
}

const SEASONS4 = [
  { slug: 'spring', name: 'Spring', emoji: '🌸', mi: [2, 3, 4], itin: 'cherry-blossom-korea-7-day-itinerary', hl: 'cherry blossoms, lantern festivals and the year\'s freshest weather' },
  { slug: 'summer', name: 'Summer', emoji: '🏖️', mi: [5, 6, 7], itin: 'first-time-korea-7-day-itinerary', hl: 'beaches, mud festivals and electric Han River nights' },
  { slug: 'autumn', name: 'Autumn', emoji: '🍁', mi: [8, 9, 10], itin: 'autumn-korea-7-day-itinerary', hl: 'fiery foliage, harvest festivals and perfect hiking weather' },
  { slug: 'winter', name: 'Winter', emoji: '❄️', mi: [11, 0, 1], itin: 'winter-korea-5-day-itinerary', hl: 'snowy palaces, ski resorts and steaming street food' },
];
function buildSeason(s) {
  const url = `${BASEP}guide/korea-in-${s.slug}.html`;
  const h1 = `Korea in ${s.name}: Things to Do, Weather & Tips`;
  const title = `${h1} (2026) | KoreaPlus`;
  const desc = `${s.name} in Korea means ${s.hl}. Month-by-month weather, what to pack and the best things to do.`;
  const trail = [{ name: 'Home', url: BASEP }, { name: 'When to Visit', url: `${BASEP}explore.html` }, { name: `Korea in ${s.name}`, url }];
  let body = bcHtml(trail);
  body += `<p class="lead">${s.name} in Korea brings ${esc(s.hl)}. Here's the season at a glance, with deep-dives for each month.</p>`;
  body += `<h2>📅 Month by month</h2>`;
  for (const i of s.mi) {
    const [name, icon, weather, , events] = MONTHS[i];
    body += `<h3>${icon} <a href="guide/korea-in-${name.toLowerCase()}.html">Korea in ${name}</a></h3><p><strong>${esc(weather)}.</strong> ${esc(events)}.</p>`;
  }
  body += `<h2>🎒 ${esc(s.name)} itinerary</h2><p>Ready-made route for the season: <a href="itinerary/${s.itin}.html">see the full day-by-day plan →</a></p>`;
  const qa = [[`Is ${s.name.toLowerCase()} a good time to visit Korea?`, `Yes — ${s.hl}. See the month pages above for exact weather and events.`]];
  body += `<h2>❓ FAQ</h2><div class="seo-faq">${qa.map(([q, a]) => `<details><summary>${esc(q)}</summary><p>${esc(a)}</p></details>`).join('')}</div>`;
  body += affHtml('🎫 Book the season', { city: s.slug === 'spring' ? 'Busan' : 'Seoul', cat: 'travel', q: '' });
  body += ctaHtml(`Planning a ${s.name.toLowerCase()} trip?`, 'Get a free AI itinerary tuned to the season.');
  const hero = `<header class="seo-hero"><span class="emoji">${s.emoji}</span><h1>${esc(h1)}</h1><div class="meta"><span class="seo-badge">3-month guide</span></div></header>`;
  const article = { '@context': 'https://schema.org', '@type': 'Article', headline: h1, description: desc, datePublished: TODAY, dateModified: TODAY, author: { '@type': 'Organization', name: 'KoreaPlus' }, publisher: { '@type': 'Organization', name: 'KoreaPlus-Lifes', logo: { '@type': 'ImageObject', url: ORIGIN + '/guide/icons/kplus.svg' } }, image: ORIGIN + '/guide/og-image.jpg', mainEntityOfPage: ORIGIN + url };
  writePage(`guide/korea-in-${s.slug}.html`, shell({ url, title, desc, keywords: '', schemas: [article, breadcrumbLD(trail), faqLD(qa)], hero, body }));
  return url;
}

// ══════════════════════════════════════════════════════════════════
// K-POP HISTORY PAGES — content from kpop-history.json
// ══════════════════════════════════════════════════════════════════
// The 9 travel languages in the order this generator has always emitted, plus
// the K-pop-only codes appended at the tail (so sitemap ordering doesn't churn).
// A language with no translation for a slug simply produces no page — both
// builders below check kpop-history.json before emitting anything.
const KPOP_HIST_LANGS = ['en', 'ko', 'ja', 'zh', 'es', 'fr', 'de', 'pt', 'id', ...KPOP_ONLY_LANGS];
const KPOP_HIST_DIR = (lang) => lang === 'en' ? '' : ((L10N[lang] && L10N[lang].dir) || lang) + '/';
const KPOP_HIST_EMOJI = { 'kpop-history': '📜', 'first-generation-kpop': '1️⃣', 'second-generation-kpop': '2️⃣', 'third-generation-kpop': '3️⃣', 'fourth-generation-kpop': '4️⃣', 'fifth-generation-kpop': '5️⃣', 'sm-entertainment-history': '🏛️', 'yg-entertainment-history': '🖤', 'jyp-entertainment-history': '💚', 'hybe-history': '💜' };
const KPOP_HIST_MORE = { en: '🎤 More K-Pop history', ko: '🎤 K-pop 역사 더보기', ja: '🎤 K-POPの歴史をもっと見る', zh: '🎤 更多 K-pop 历史', es: '🎤 Más historia del K-pop', fr: '🎤 Plus d\'histoire de la K-pop', de: '🎤 Mehr K-Pop-Geschichte', pt: '🎤 Mais história do K-pop', id: '🎤 Sejarah K-pop lainnya', ar: '🎤 المزيد عن تاريخ K-Pop', hi: '🎤 K-Pop इतिहास के और गाइड', ru: '🎤 Ещё об истории K-pop', vi: '🎤 Thêm về lịch sử K-pop', th: '🎤 ประวัติ K-pop เพิ่มเติม' };
// Years that actually got a kpop-releases-<year> page. Filled from
// mKpopYear.YEARS after the modules are instantiated (that happens further down,
// but every buildKpopHistory call happens later still), so the discography's
// Year column can only ever link to a page that exists.
const KPOP_YEAR_PAGES = new Set();
function buildKpopHistory(slug, lang) {
  const byLang = KPOP_HIST[slug]; const t = byLang && byLang[lang];
  if (!t) return null;
  const dir = KPOP_HIST_DIR(lang);
  const url = `${BASEP}${dir}kpop/${slug}.html`;
  const enUrl = `${BASEP}kpop/${slug}.html`;
  // Standalone K-Pop channel: breadcrumb root is the K-Pop hub (/kpop), not the
  // travel-guide home — keeps users inside the K-Pop property.
  const trail = [{ name: 'K-Pop', url: '/kpop' }, { name: t.h1, url }];
  // Roster act? Then we have a licence-verified photo and a dated release list
  // for it — the prose sections describe the discography, these show it.
  const rosterId = /-profile$/.test(slug) ? slug.replace('-profile', '') : null;
  const rosterAct = rosterId ? KPOP_ROSTER.find(r => r.id === rosterId) : null;
  let body = bcHtml(trail);
  if (rosterAct) body += __kpm.photoFigure(KPOP_IMAGES, rosterId, rosterAct.nameEn || t.h1, lang, esc);
  body += `<p class="lead">${esc(t.lead)}</p>`;
  for (const s of (t.sections || [])) body += `<h2>${esc(s.h)}</h2>${(s.body || '').trim().startsWith('<') ? s.body : `<p>${esc(s.body)}</p>`}`;
  // Structured discography after the prose: the article says what mattered,
  // the table says exactly what came out and when.
  if (rosterAct) body += __kpm.discogSection(KPOP_DISCOG, rosterId, lang, TODAY_KST, esc, KPOP_YEAR_PAGES, dir);
  const qa = (t.faq || []).map(x => Array.isArray(x) ? x : [x.q, x.a]);
  if (qa.length) body += `<h2>❓ FAQ</h2><div class="seo-faq">${qa.map(([q, a]) => `<details><summary>${esc(q)}</summary><p>${esc(a)}</p></details>`).join('')}</div>`;
  const sibs = Object.keys(KPOP_HIST).filter(s2 => s2 !== slug && KPOP_HIST[s2] && KPOP_HIST[s2][lang]).slice(0, 9);
  const browseLabel = (KPOP_BROWSE_T[lang] || KPOP_BROWSE_T.en).more;
  body += `<h2>${esc(KPOP_HIST_MORE[lang] || KPOP_HIST_MORE.en)}</h2><div class="seo-linklist">${sibs.map(s2 => `<a href="${dir}kpop/${s2}.html">${KPOP_HIST_EMOJI[s2] || '🎶'} ${esc(KPOP_HIST[s2][lang].h1)}</a>`).join('')}<a href="${dir}kpop/browse.html">${esc(browseLabel)}</a><a href="/kpop">🎤 K-Pop Hub</a></div>`;
  body += affBlock({ city: 'Seoul', cat: 'general', q: '', lang });
  const hero = `<header class="seo-hero"><span class="emoji">${KPOP_HIST_EMOJI[slug] || '🎤'}</span><h1>${esc(t.h1)}</h1><div class="meta"><span class="seo-badge">K-Pop</span><span class="seo-badge">2026</span></div></header>`;
  const article = { '@context': 'https://schema.org', '@type': 'Article', headline: t.h1, description: t.metaDesc, inLanguage: lang, datePublished: TODAY, dateModified: TODAY, author: { '@type': 'Organization', name: 'KoreaPlus' }, publisher: { '@type': 'Organization', name: 'KoreaPlus-Lifes', logo: { '@type': 'ImageObject', url: ORIGIN + '/guide/icons/kplus.svg' } }, image: ORIGIN + '/guide/og-image.jpg', mainEntityOfPage: ORIGIN + url };
  // K08 — MusicGroup schema on artist *-profile pages (joined to KPOP_ROSTER
  // by id). sameAs only from VERIFIED external ids; members listed by name
  // with NO birthDate (per-member bdays absent → never fabricated).
  let musicGroup = null;
  if (rosterAct) {
    const a = rosterAct;
    const sameAs = [];
    if (a.wikidataId && /^Q\d+$/.test(a.wikidataId)) sameAs.push('https://www.wikidata.org/wiki/' + a.wikidataId);
    if (a.spotifyId && /^[A-Za-z0-9]+$/.test(a.spotifyId)) sameAs.push('https://open.spotify.com/artist/' + a.spotifyId);
    if (a.youtubeChannelId && /^[A-Za-z0-9_-]+$/.test(a.youtubeChannelId)) sameAs.push('https://www.youtube.com/channel/' + a.youtubeChannelId);
    // Prefer the act's own Commons photo over the site's generic OG card.
    const photo = KPOP_IMAGES[rosterId] && KPOP_IMAGES[rosterId].src;
    musicGroup = __ld.musicGroupLD({
      name: a.nameEn || t.h1,
      alternateName: a.nameKo,
      genre: Array.isArray(a.genres) ? a.genres : undefined,
      foundingDate: a.debut,
      url: ORIGIN + url,
      sameAs,
      image: photo || (ORIGIN + '/guide/og-image.jpg'),
      members: Array.isArray(a.members) ? a.members.map(m => ({ name: m })) : undefined, // no birthDate — never fabricated
      origin: ORIGIN,
    });
    // Dated releases from the Apple snapshot — same source as the visible table.
    const albums = __kpm.albumSchema(KPOP_DISCOG, rosterId, 12, TODAY_KST);
    if (musicGroup && albums.length) musicGroup.album = albums;
  }
  const others = KPOP_HIST_LANGS.filter(l => l !== lang && KPOP_HIST[slug][l]);
  // KPOP_HIST_DIR, not L10N[l].dir: the latter throws on any language that has
  // no L10N row at all. It already carries the trailing slash.
  const alts = lang === 'en'
    ? others.map(l => ({ lang: l, url: `${BASEP}${KPOP_HIST_DIR(l)}kpop/${slug}.html` }))
    : [{ lang: 'en', url: enUrl }, ...others.filter(l => l !== 'en').map(l => ({ lang: l, url: `${BASEP}${KPOP_HIST_DIR(l)}kpop/${slug}.html` }))];
  writePage(`${dir}kpop/${slug}.html`, shell({ url, title: t.title, desc: t.metaDesc, keywords: '', schemas: [article, musicGroup, breadcrumbLD(trail), faqLD(qa)].filter(Boolean), hero, body, lang, alts, homeHref: '/kpop', brand: '🎤 Korea<span>Plus</span>' }));
  return url;
}

